@FunctionalInterface
interface Validator {
    boolean isValid(String input);
    default boolean isInvalid(String input) {
        return !isValid(input);
    }
}

class Printer {
    @SafeVarargs
    public <T> void printItems(T... items) {}
}

import java.lang.annotation.*;
@Target(ElementType.FIELD)
@interface FieldOnly {}

class Test {
    void run() {
        @FieldOnly int x = 10;
    }
}

import java.lang.annotation.*;
@Inherited
@Retention(RetentionPolicy.RUNTIME)
@interface MyTag {}

@MyTag interface Custom {}
class Parent implements Custom {}

public class Main {
    public static void main(String[] args) {
        System.out.println(Parent.class.isAnnotationPresent(MyTag.class));
    }
}

import java.lang.annotation.*;
@Repeatable(Tags.class)
@interface Tag {
    String value();
}
@interface Tags {
    Tag[] value();
}

@interface Info {
    String value();
    int level() default 1;
}

@Info("Demo")
class Main {}

import java.lang.annotation.*;

@Target(ElementType.TYPE)
@interface ServiceConfig {}

class Demo {
    @ServiceConfig
    void doSomething() {}
}

import java.lang.annotation.*;

@Inherited
@Retention(RetentionPolicy.RUNTIME)
@interface Tx {}

@Tx
interface Service {}

class MyService implements Service {}

public class Test {
    public static void main(String[] args) {
        System.out.println(MyService.class.isAnnotationPresent(Tx.class));
    }
}

import java.lang.annotation.*;

// No @Retention specified (default is CLASS)
@interface WebRoute {
    String path();
}

@WebRoute(path = "/home")
class IndexController {}

public class App {
    public static void main(String[] args) {
        System.out.println(IndexController.class.isAnnotationPresent(WebRoute.class));
    }
}

import java.lang.annotation.*;

@Retention(RetentionPolicy.RUNTIME)
@interface Roles {
    Role[] value();
}

@Repeatable(Roles.class)
@Retention(RetentionPolicy.RUNTIME)
@interface Role {
    String value();
}

@Role("ADMIN")
@Role("USER")
class Dashboard {}

public class Test {
    public static void main(String[] args) {
        System.out.println(Dashboard.class.isAnnotationPresent(Role.class));
    }
}

@interface ProjectInfo {
    String name();
    java.util.Date launchDate();
}

import java.lang.annotation.*;
@Retention(RetentionPolicy.RUNTIME)
@interface NonInherited {}

@NonInherited
class Parent {}
class Child extends Parent {}

public class Main {
    public static void main(String[] args) {
        System.out.println(Child.class.isAnnotationPresent(NonInherited.class));
    }
}

import java.util.*;
class Accumulator {
    @SafeVarargs
    public <T> void addItems(T... items) {}
}

import java.lang.annotation.*;
@Retention(RetentionPolicy.RUNTIME)
@interface Roles {
    Role[] value();
}
@Repeatable(Roles.class)
@Retention(RetentionPolicy.RUNTIME)
@interface Role {
    String value();
}
@Role("Manager")
@Role("Staff")
class User {}
public class Main {
    public static void main(String[] args) {
        System.out.println(User.class.getAnnotation(Role.class));
    }
}

class Base {
    public void setRate(double rate) {}
}
class Sub extends Base {
    @Override
    public void setRate(Double rate) {}
}

import java.lang.annotation.*;
import java.lang.reflect.Proxy;

@Retention(RetentionPolicy.RUNTIME)
@interface MyCheck {}

@MyCheck
class Target {}

public class Main {
    public static void main(String[] args) {
        MyCheck c = Target.class.getAnnotation(MyCheck.class);
        System.out.println(Proxy.isProxyClass(c.getClass()));
    }
}

@interface DatabaseConfig {
    String value();
    String[] tables();
    int[][] matrix() default {};
}
